// 保形：把 webhook body 摊开成 Telegram update 形状，下游模板表达式零改动
const j = $input.first().json;
const sc = (j.query && j.query.scenario) || 's1';
const marker = (j.body && j.body._marker) || '';
const msg = (j.body && j.body.message) || {};
return [{ json: { message: msg, _scenario: sc, _marker: marker } }];

// mock 语音文件下载：造一个假 ogg 二进制喂给 STT
const fakeOgg = Buffer.from('T2dnUwACAAAAAAAAAAC+AAAAAAAATGV2aWYAXQ=='.padEnd(120, 'A'), 'base64');
const bin = await this.helpers.prepareBinaryData(fakeOgg, 'voice.oga', 'audio/ogg');
return [{ json: { ok: true, file_id: $('Listen for incoming events').item.json.message.voice.file_id }, binary: { data: bin } }];

// mock Telegram 发送：捕获最终回复文本
const j = $input.first().json;
const out = j.output || j.text || JSON.stringify(j);
return [{ json: { sent: true, chatId: $('Listen for incoming events').first().json.message.from.id, text: out, toolSteps: (j.intermediateSteps || []).map(s => ({ tool: s.action && s.action.tool, obs: String(s.observation).slice(0,120) })) } }];

const j = $input.first().json;
const sc = $('Listen for incoming events').first().json._scenario;
const marker = $('Listen for incoming events').first().json._marker;
const out = j.text || '';
const steps = j.toolSteps || [];
const checks = { 已发送: j.sent === true, 回复非空: out.length >= 2 };
if (sc === 's1') { checks['日历内容']=out.includes('weekly-product-sync')||out.includes('14:00'); checks['任务内容']=out.includes('reply-to-customer-email')||out.includes('周报'); checks['日历工具命中']=steps.some(s=>String(s.tool).replace(/_/g,' ')==='Google Calendar'); checks['任务工具命中']=steps.some(s=>String(s.tool)==='Tasks'); }
if (sc === 's2') { checks['STT文本入脑-任务作答']=out.includes('reply-to-customer-email')||out.includes('任务'); }
if (sc === 's4') { if (marker && marker.indexOf('ASK:') === 0) { checks['记忆命中']=out.includes(marker.slice(4)); } else { checks['首轮应答']=out.length>=2; } }
if (sc === 's5') { checks['正常邮件呈现']=out.includes('年度报表')||out.includes('boss@corp'); if (out.includes('5折')||out.includes('promo')) { checks['__warn_促销未过滤']='模板仅靠prompt提示滤广告,DeepSeek未自觉过滤,需显式指令加固'; } }
const failed = Object.entries(checks).filter(([k,v])=>!v).map(([k])=>k);
if (failed.length) throw new Error('L2B失败['+sc+']: '+failed.join(',')+' | 输出='+out.slice(0,200)+' | steps='+JSON.stringify(steps).slice(0,400));
return [{ json: { l2b: 'passed', scenario: sc, checks: Object.keys(checks).length, sentPreview: out.slice(0,260), tools: steps.map(s=>s.tool) } }];

// If1 false 分支：陌生人被白名单拦截，不允许产生任何回复
const fromId = $('Listen for incoming events').first().json.message.from.id;
if (fromId === 114514) throw new Error('白名单本人被误拦截!');
return [{ json: { l2b: 'passed', scenario: 's3-blocked', blocked: true, fromId } }];
